//! `MessageTranslator` — Anthropic SSE events → `ModelEvent` stream.

use std::collections::HashMap;

use paigasus_helikon_core::{FinishReason, ModelError, ModelEvent};

use crate::error::map_error_type;
use crate::provider_data::{AnthropicData, ThinkingBlock};
use crate::sse::{
    AnthropicEvent, ContentBlockDelta, ContentBlockHead, MessageDeltaUsage, MessageStartUsage,
};
use crate::translate::response_format::SYNTHESIZED_TOOL_NAME;

#[derive(Debug)]
enum BlockState {
    Text,
    Thinking {
        text: String,
        signature: String,
    },
    RedactedThinking {
        data: String,
    },
    ToolUse {
        call_id: String,
        name: String,
        name_emitted: bool,
    },
}

/// State machine for one streaming response.
///
/// `synthesizing_output: true` means a `ResponseFormat::JsonSchema`/`JsonObject`
/// request was sent. When the synthesized tool's content block starts, its
/// `input_json_delta` events are remapped to `TokenDelta`s and the
/// `stop_reason: "tool_use"` is rewritten to `Stop` if it was the only tool fired.
pub(crate) struct MessageTranslator {
    blocks: HashMap<u32, BlockState>,
    last_input_tokens: u32,
    last_cached_input_tokens: Option<u32>,
    stop_reason: Option<String>,
    synthesizing_output: bool,
    synthesized_tool_index: Option<u32>,
    other_tool_fired: bool,
    terminal_emitted: bool,
    /// The first text block of the response has stopped.
    text_position_recorded: bool,
    /// The stream has emitted a `block` part of this response.
    block_emitted: bool,
    /// Position records that wait for the first `block` part.
    waiting_positions: Vec<ModelEvent>,
}

impl MessageTranslator {
    pub(crate) fn new(synthesizing_output: bool) -> Self {
        Self {
            blocks: HashMap::new(),
            last_input_tokens: 0,
            last_cached_input_tokens: None,
            stop_reason: None,
            synthesizing_output,
            synthesized_tool_index: None,
            other_tool_fired: false,
            terminal_emitted: false,
            text_position_recorded: false,
            block_emitted: false,
            waiting_positions: Vec::new(),
        }
    }

    /// Consume one event. Returns the emitted ModelEvents (most calls
    /// emit zero or one; `message_delta` carrying both stop_reason and
    /// usage emits one Usage followed by Finish on `message_stop`). A
    /// terminal event (`Finish` or an `Err`) is emitted at most once per
    /// stream, and a later `message_delta`'s `Usage` is suppressed once one
    /// has been emitted. Content deltas are deliberately *not* guarded: a
    /// malformed stream that keeps sending `content_block_delta` after
    /// `message_stop` would still yield them. A clean end-of-stream flush of
    /// a buffered stop reason with no terminal event yet is handled
    /// separately by `finish()`.
    pub(crate) fn consume(
        &mut self,
        event: AnthropicEvent,
    ) -> Result<Vec<Result<ModelEvent, ModelError>>, ModelError> {
        let mut out: Vec<Result<ModelEvent, ModelError>> = Vec::new();
        match event {
            AnthropicEvent::MessageStart { message } => {
                let MessageStartUsage {
                    input_tokens,
                    cache_read_input_tokens,
                    ..
                } = message.usage;
                self.last_input_tokens = input_tokens;
                self.last_cached_input_tokens = cache_read_input_tokens;
                out.push(Ok(ModelEvent::Usage {
                    input_tokens,
                    output_tokens: 0,
                    cached_input_tokens: cache_read_input_tokens,
                    reasoning_tokens: None,
                }));
            }
            AnthropicEvent::ContentBlockStart {
                index,
                content_block,
            } => match content_block {
                ContentBlockHead::Text => {
                    self.blocks.insert(index, BlockState::Text);
                }
                ContentBlockHead::Thinking {
                    thinking,
                    signature,
                } => {
                    self.blocks.insert(
                        index,
                        BlockState::Thinking {
                            text: thinking,
                            signature,
                        },
                    );
                }
                ContentBlockHead::RedactedThinking { data } => {
                    self.blocks
                        .insert(index, BlockState::RedactedThinking { data });
                }
                ContentBlockHead::ToolUse { id, name, .. } => {
                    if self.synthesizing_output && name == SYNTHESIZED_TOOL_NAME {
                        self.synthesized_tool_index = Some(index);
                    } else {
                        self.other_tool_fired = true;
                    }
                    self.blocks.insert(
                        index,
                        BlockState::ToolUse {
                            call_id: id,
                            name,
                            name_emitted: false,
                        },
                    );
                }
            },
            AnthropicEvent::ContentBlockDelta { index, delta } => match delta {
                ContentBlockDelta::TextDelta { text } => {
                    out.push(Ok(ModelEvent::TokenDelta { text }));
                }
                ContentBlockDelta::ThinkingDelta { thinking } => {
                    if let Some(BlockState::Thinking { text, .. }) = self.blocks.get_mut(&index) {
                        text.push_str(&thinking);
                    }
                    out.push(Ok(ModelEvent::ReasoningDelta { text: thinking }));
                }
                ContentBlockDelta::SignatureDelta { signature } => {
                    if let Some(BlockState::Thinking {
                        signature: joined, ..
                    }) = self.blocks.get_mut(&index)
                    {
                        joined.push_str(&signature);
                    } else {
                        tracing::debug!(
                            target: "paigasus::anthropic::stream",
                            index,
                            "signature_delta for a block that is not open; dropped",
                        );
                    }
                }
                ContentBlockDelta::InputJsonDelta { partial_json } => {
                    let is_synth = Some(index) == self.synthesized_tool_index;
                    if is_synth {
                        out.push(Ok(ModelEvent::TokenDelta { text: partial_json }));
                    } else if let Some(BlockState::ToolUse {
                        call_id,
                        name,
                        name_emitted,
                    }) = self.blocks.get_mut(&index)
                    {
                        let (emit_name, call_id_out) = if *name_emitted {
                            (None, call_id.clone())
                        } else {
                            *name_emitted = true;
                            (Some(name.clone()), call_id.clone())
                        };
                        out.push(Ok(ModelEvent::ToolCallDelta {
                            call_id: call_id_out,
                            name: emit_name,
                            args_delta: partial_json,
                        }));
                    } else {
                        // Protocol violation: input_json_delta only ever
                        // applies to a tool_use content block. Surface it
                        // rather than silently dropping (which would mask
                        // a malformed upstream stream).
                        return Err(ModelError::Transport(format!(
                            "anthropic stream: input_json_delta at index {index} \
                             has no preceding tool_use content_block_start"
                        )));
                    }
                }
            },
            AnthropicEvent::ContentBlockStop { index } => {
                self.stop_block(index, &mut out);
            }
            AnthropicEvent::MessageDelta { delta, usage } => {
                // A `message_delta` after the terminal event is a protocol
                // violation (e.g. a second `message_delta` re-arming
                // `stop_reason` post-`message_stop`, see
                // `second_message_delta_after_message_stop_does_not_double_finish`).
                // Emitting its `Usage` would put an event after `Finish`,
                // which the core contract forbids.
                if !self.terminal_emitted {
                    if let Some(MessageDeltaUsage { output_tokens }) = usage {
                        out.push(Ok(ModelEvent::Usage {
                            input_tokens: self.last_input_tokens,
                            output_tokens,
                            cached_input_tokens: self.last_cached_input_tokens,
                            reasoning_tokens: None,
                        }));
                    }
                }
                if let Some(reason) = delta.stop_reason {
                    self.stop_reason = Some(reason);
                }
            }
            AnthropicEvent::MessageStop => {
                if let Some(reason) = self.stop_reason.take() {
                    if !self.terminal_emitted {
                        self.terminal_emitted = true;
                        out.push(self.finish_or_error(&reason));
                    }
                }
            }
            AnthropicEvent::Ping => {}
            AnthropicEvent::Error { error } => {
                return Err(map_error_type(None, &error.ty, &error.message, None));
            }
        }
        Ok(out)
    }

    /// Close the block at `index`: keep a valid thinking block and record the
    /// positions of the text and `tool_use` blocks.
    fn stop_block(&mut self, index: u32, out: &mut Vec<Result<ModelEvent, ModelError>>) {
        // No event can follow `Finish`, so a block stop after the terminal
        // event gives no provider data.
        if self.terminal_emitted {
            tracing::debug!(
                target: "paigasus::anthropic::stream",
                index,
                "content_block_stop after the terminal event",
            );
            return;
        }
        let Some(state) = self.blocks.remove(&index) else {
            tracing::debug!(
                target: "paigasus::anthropic::stream",
                index,
                "content_block_stop for a block that is not open",
            );
            return;
        };
        match state {
            BlockState::Thinking { text, signature } => self.keep_block(
                index,
                "thinking",
                ThinkingBlock::Thinking {
                    thinking: text,
                    signature,
                },
                out,
            ),
            BlockState::RedactedThinking { data } => self.keep_block(
                index,
                "redacted_thinking",
                ThinkingBlock::RedactedThinking { data },
                out,
            ),
            BlockState::Text => {
                if !self.text_position_recorded {
                    self.text_position_recorded = true;
                    self.position(AnthropicData::Text { index }.into_event(None), out);
                }
            }
            BlockState::ToolUse {
                call_id,
                name_emitted,
                ..
            } => {
                if name_emitted && Some(index) != self.synthesized_tool_index {
                    self.position(
                        AnthropicData::ToolUse { index }.into_event(Some(call_id)),
                        out,
                    );
                }
            }
        }
    }

    /// Emit a valid thinking block, then every position that waits for it.
    fn keep_block(
        &mut self,
        index: u32,
        kind: &str,
        block: ThinkingBlock,
        out: &mut Vec<Result<ModelEvent, ModelError>>,
    ) {
        if !block.is_valid() {
            tracing::debug!(
                target: "paigasus::anthropic::stream",
                index,
                kind,
                "thinking block without signature or data is not kept",
            );
            return;
        }
        out.push(Ok(AnthropicData::Block { index, block }.into_event(None)));
        if !self.block_emitted {
            self.block_emitted = true;
            out.extend(self.waiting_positions.drain(..).map(Ok));
        }
    }

    /// Emit a position record now, or hold it until the first `block` part.
======
//! The private `data` shapes of the `ProviderData` parts and events.
//!
//! The stream writes these shapes under [`PROVIDER_DATA_KEY`]. The shapes are
//! private to this crate and can change. A host must not parse them.

use paigasus_helikon_core::{ContentPart, ModelEvent};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use crate::PROVIDER_DATA_KEY;

/// One thinking block of a response, as Anthropic sent it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub(crate) enum ThinkingBlock {
    /// A `thinking` block with its text and its signature.
    Thinking {
        /// The joined thinking text. It can be empty.
        thinking: String,
        /// The signature that Anthropic checks on a later request.
        signature: String,
    },
    /// A `redacted_thinking` block with its opaque data.
    RedactedThinking {
        /// The opaque data that Anthropic checks on a later request.
        data: String,
    },
}

impl ThinkingBlock {
    /// A block is valid when Anthropic can check it on a later request.
    ///
    /// A `thinking` block needs a non-empty signature. Its text can be empty.
    /// A `redacted_thinking` block needs non-empty data.
    pub(crate) fn is_valid(&self) -> bool {
        match self {
            Self::Thinking { signature, .. } => !signature.is_empty(),
            Self::RedactedThinking { data } => !data.is_empty(),
        }
    }

    /// The block in its request form.
    ///
    /// The form holds only `type` and the known fields of the block. A field
    /// that the stored data has in addition is not sent.
    pub(crate) fn to_wire(&self) -> Value {
        match self {
            Self::Thinking {
                thinking,
                signature,
            } => json!({
                "type": "thinking",
                "thinking": thinking,
                "signature": signature,
            }),
            Self::RedactedThinking { data } => json!({
                "type": "redacted_thinking",
                "data": data,
            }),
        }
    }

    /// The Anthropic block type, for log lines.
    fn type_name(&self) -> &'static str {
        match self {
            Self::Thinking { .. } => "thinking",
            Self::RedactedThinking { .. } => "redacted_thinking",
        }
    }
}

/// The `data` of one `ProviderData` part or event of this crate.
///
/// `index` is the Anthropic content-block index in the response.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub(crate) enum AnthropicData {
    /// A thinking block.
    Block {
        /// The content-block index of the block.
        index: u32,
        /// The block itself.
        block: ThinkingBlock,
    },
    /// The position of the first text block of the response.
    Text {
        /// The content-block index of the text block.
        index: u32,
    },
    /// The position of a `tool_use` block.
    ToolUse {
        /// The content-block index of the `tool_use` block.
        index: u32,
    },
}

impl AnthropicData {
    /// Make the `ModelEvent` that carries this data.
    pub(crate) fn into_event(self, call_id: Option<String>) -> ModelEvent {
        ModelEvent::ProviderData {
            provider: PROVIDER_DATA_KEY.to_owned(),
            call_id,
            data: serde_json::to_value(self).expect("AnthropicData serializes"),
        }
    }
}

/// Read the data of one part of this crate.
///
/// Returns `None` with no log for a part that is not `ProviderData` or that
/// has the key of another provider. Returns `None` with a debug log for a part
/// with this key that does not parse, or that holds a block that is not valid.
/// The log never holds the content of the part.
pub(crate) fn from_part(part: &ContentPart) -> Option<(AnthropicData, Option<&str>)> {
    let ContentPart::ProviderData {
        provider,
        call_id,
        data,
    } = part
    else {
        return None;
    };
    if provider != PROVIDER_DATA_KEY {
        return None;
    }
    // The parse error is not logged, because it can hold a value of the data.
    let Ok(parsed) = AnthropicData::deserialize(data) else {
        tracing::debug!(
            target: "paigasus::anthropic::translate",
            "skipping anthropic provider data that does not parse",
        );
        return None;
    };
    if let AnthropicData::Block { index, block } = &parsed {
        if !block.is_valid() {
            tracing::debug!(
                target: "paigasus::anthropic::translate",
                index = *index,
                block_type = block.type_name(),
                "skipping anthropic thinking block that is not valid",
            );
            return None;
        }
    }
    Some((parsed, call_id.as_deref()))
}

/// Make a `ProviderData` part of this crate (test helper).
#[cfg(test)]
pub(crate) fn part(data: AnthropicData, call_id: Option<&str>) -> ContentPart {
    ContentPart::ProviderData {
        provider: PROVIDER_DATA_KEY.to_owned(),
        call_id: call_id.map(str::to_owned),
        data: serde_json::to_value(data).expect("AnthropicData serializes"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn data_serializes_to_the_documented_shapes() {
        let thinking = AnthropicData::Block {
            index: 0,
            block: ThinkingBlock::Thinking {
                thinking: "t".to_owned(),
                signature: "SIG_FAKE_1".to_owned(),
            },
        };
        assert_eq!(
            serde_json::to_value(&thinking).unwrap(),
            json!({"kind":"block","index":0,"block":{"type":"thinking","thinking":"t","signature":"SIG_FAKE_1"}})
        );
        let redacted = AnthropicData::Block {
            index: 1,
            block: ThinkingBlock::RedactedThinking {
                data: "REDACTED_FAKE_1".to_owned(),
            },
